        sum_buf = torch.zeros(batch_size, dtype=torch.float64, device=x.device)
        sumsq_buf = torch.zeros(batch_size, dtype=torch.float32, device=x.device)
        counter1_buf = torch.zeros(batch_size, dtype=torch.int32, device=x.device)
        counter2_buf = torch.zeros(batch_size, dtype=torch.int32, device=x.device)
        ready1_buf = torch.zeros(batch_size, dtype=torch.int32, device=x.device)
        ready2_buf = torch.zeros(batch_size, dtype=torch.int32, device=x.device)
        mean_buf = torch.empty(batch_size, dtype=torch.float32, device=x.device)
        invstd_buf = torch.empty(batch_size, dtype=torch.float32, device=x.device)
        module = _get_ptx_module()
        module.launch(
            "layernorm_kernel",
            grid=(batch_size, num_splits, 1),
            block=(512, 1, 1),
            arguments=[
                x, output, weight, bias, i32(n_elements),
                sum_buf, sumsq_buf, counter1_buf, counter2_buf,
                ready1_buf, ready2_buf, mean_buf, invstd_buf,
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output

